pub mod text{#[derive(Clone,Debug,PartialEq,Eq)]pub struct Text(String);impl Text{pub fn literal(s:impl Into<String>)->Self{Self(s.into())}pub fn push(&mut self,t:Self){self.0.push_str(&t.0);}pub fn plain(&self)->String{self.0.clone()}}}
pub mod scoreboard{pub fn comp_text(s:&String)->crate::text::Text{crate::text::Text::literal(s)}}
pub mod tab_list{#[derive(Clone)]pub struct TabPlayer{pub uuid:u128,pub name:String,pub latency:i32,pub display_name:Option<String>,pub game_mode:i32}}
#[test]fn exact_filters_colors_limits_and_actual_render_policy(){use better_tab::*;let mut s=BetterTab::default();assert_eq!(s.color("Me",None,"Me",true),Ok(Some(0x5032c132)));assert_eq!(s.color("Friend",None,"Me",true),Ok(Some(0x501059cb)));assert_eq!(s.color("Other",None,"Me",false),Ok(None));s.others_filter.names.push(Some(Pattern::new("(?i)other").unwrap()));assert_eq!(s.color("Other",None,"Me",false),Ok(Some(0x50232323)));assert!(!s.others_filter.matches("OtherSuffix",None).unwrap());s.hider_filter.names.push(None);s.hider_filter.filter_by=1;assert_eq!(s.hider_filter.matches("a",None),Ok(false));s.hider_filter.filter_by=2;assert!(s.hider_filter.matches("a",None).is_err());assert_eq!(s.latency(-5),("0ms".into(),0xff00e970));assert_eq!(s.latency(200),("200ms".into(),0xffe7d020));assert_eq!(s.latency(12000),("9999ms".into(),0xffd74238));assert_eq!(s.dimensions(81),Ok((4,20)));s.column_height=-1;assert_eq!(s.dimensions(81),Ok((80,1)));s.tab_size=-2;assert!(s.dimensions(2).is_err());
 let rows=vec![tab_list::TabPlayer{uuid:1,name:"z".into(),latency:200,display_name:None,game_mode:3},tab_list::TabPlayer{uuid:2,name:"A".into(),latency:-1,display_name:Some("xx".into()),game_mode:1}];let json=serde_json::json!({"sorting":1,"visibility":3,"showGameMode":true,"limit":100,"height":1,"accurate":true,"suffix":false,"rows":{"1":{"hidden":false,"color":1345503538i32},"2":{"hidden":false,"color":null}},"error":null}).to_string();let scope=better_tab_render::scope(&json);assert_eq!(better_tab_render::ordered(&rows,rows.iter().collect()).iter().map(|p|p.uuid).collect::<Vec<_>>(),vec![2,1]);assert_eq!(better_tab_render::name(&rows[0],text::Text::literal("z")).plain(),"z [S]");assert_eq!(better_tab_render::dimensions(2,(1,2)),(2,1));assert_eq!(better_tab_render::width_extra(),30);assert_eq!(better_tab_render::latency(500).unwrap().0.plain(),"500");drop(scope);assert_eq!(better_tab_render::width_extra(),0);assert!(better_tab_render::latency(1).is_none());}
